import React from 'react'
import { QpuCard } from '@/components/qpu/card'
import { QpuBadge } from '@/components/qpu/badge'
export const QpuStream: React.FC<{ blocks: { address: string; kind?: string; date?: string; [k: string]: unknown }[] }> = ({ blocks }) => (
  <div style={{ display: 'grid', gap: 8 }}>
    {[...blocks].reverse().map((b) => <QpuCard key={b.address} uuid={b.address} title={b.kind ?? 'block'}><QpuBadge uuid={b.address} /> <small>{b.date ?? ''}</small></QpuCard>)}
  </div>
)
